+export function traverseSerial<T, U, E>(
+  itemsOrFn: Iterable<T> | ((item: T) => Task<U, E>),
+  taskFn?: (item: T) => Task<U, E>
+): Task<U[], E> | ((items: Iterable<T>) => Task<U[], E>) {
+  if (taskFn === undefined) return (items) => traverseSerial(items, itemsOrFn as (item: T) => Task<U, E>);
+
+  return new Task((resolve, reject) => {
+    const iterator = (itemsOrFn as Iterable<T>)[Symbol.iterator]();
+    const values: U[] = [];
+    const advance = () => {
+      const next = iterator.next();
+      if (next.done) {
+        resolve(values);
+        return;
+      }
+      taskFn(next.value).match({
+        Resolved: (value) => {
+          values.push(value);
+          advance();
+        },
+        Rejected: reject,
+      });
+    };
+    advance();
+  });
+}
+
+export function zip<T, U, E>(a: Task<T, E>, b: Task<U, E>): Task<[T, U], E> {
+  return new Task((resolve, reject) => {
+    Promise.all([a, b]).then(([aResult, bResult]) => {
+      if (aResult.isErr) reject(aResult.error);
+      else if (bResult.isErr) reject(bResult.error);
+      else resolve([aResult.value, bResult.value]);
+    });
+  });
+}
